from collections import Counter
from pathlib import Path

def fasta(data):
    out=[]; h=None; s=[]
    for line in data.decode().splitlines():
        if line.startswith('>'):
            if h is not None: out.append((h,''.join(s)))
            h=line[1:]; s=[]
        else:s.append(line.strip())
    if h is not None:out.append((h,''.join(s)))
    return out

def pis(seqs, gm=True):
  c=0
  for j in range(len(seqs[0][1])):
    col=[s[j] for _,s in seqs]
    if gm: col=[x for x in col if x not in '-?X']
    if sum(v>=2 for v in Counter(col).values())>=2:c+=1
  return c

def load(gm):
  out={}
  for group in ['animals','fungi']:
    with ZipFile(Path('inputs')/f'scogs_{group}.zip') as z:
      for name in z.namelist():
        if name.endswith('.mafft'):out[group,name]=pis(fasta(z.read(name)),gm)
  return out

def mw(x,y):
  vals=sorted(x+y); rank={}; i=0
  while i<len(vals):
    j=i+1
    while j<len(vals) and vals[j]==vals[i]:j+=1
    rank[vals[i]]=(i+1+j)/2;i=j
  u=sum(rank[v] for v in x)-len(x)*(len(x)+1)/2
  return u,len(x)*len(y)-u,min(u,len(x)*len(y)-u)
for gm in [True,False]:
